#Requires -Version 7.0
# Round2 review step 3: list recent ClaudeCode sessions/turns via client.SessionLog.QueryAsync to locate the hook turn.
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$plugin = '<home>/github/mcpserver-claude-code-plugin'
$ws = '<repo>'
$wrapper = Join-Path $plugin 'lib/Invoke-McpPlugin.ps1'
Set-Location -LiteralPath $ws
. (Join-Path $plugin 'lib/yaml-object-mutation.ps1')
Import-McpYamlSerializer
$bom = [string][char]0xFEFF
$target = 'req-20261029T014733Z-prompt-4388'
$raw = & $wrapper -Command Invoke -Method 'client.SessionLog.QueryAsync' -ParamsObject ([ordered]@{ agent = 'ClaudeCode'; limit = 4 }) -WorkspacePath $ws -PluginRoot $plugin 2>$null
$text = ($raw | Out-String).Replace($bom, '')
$doc = ConvertFrom-Yaml -Yaml $text
$result = $doc['payload']['result']
$items = if ($result -is [System.Collections.IDictionary] -and $result.Contains('items')) { @($result['items']) } else { @($result) }
Write-Output ("QUERY type={0} sessions={1}" -f $doc['type'], $items.Count)
foreach ($s in $items) {
    if ($null -eq $s) { continue }
    $turns = @($s['turns'] | Where-Object { $null -ne $_ })
    Write-Output ("SESSION {0} status={1} model={2} turns={3} lastUpdated={4}" -f $s['sessionId'], $s['status'], $s['model'], $turns.Count, $s['lastUpdated'])
    foreach ($t in ($turns | Select-Object -Last 4)) {
        $rid = [string]$t['requestId']
        $mark = if ($rid -eq $target) { ' <== HOOK TURN' } else { '' }
        Write-Output ("  TURN {0} status={1} title={2} dialog={3} actions={4}{5}" -f $rid, $t['status'], $t['queryTitle'], @($t['processingDialog'] | Where-Object { $null -ne $_ }).Count, @($t['actions'] | Where-Object { $null -ne $_ }).Count, $mark)
    }
}
$cacheRoots = @(Join-Path $ws '.mcpServer/claude')
if ($env:CLAUDE_PLUGIN_ROOT) { $cacheRoots += (Join-Path $env:CLAUDE_PLUGIN_ROOT 'cache') }
foreach ($c in $cacheRoots) {
    if (-not (Test-Path -LiteralPath $c)) { continue }
    Get-ChildItem -LiteralPath $c -Recurse -File -Filter 'current-turn*.yaml' -ErrorAction SilentlyContinue | ForEach-Object {
        $hit = Select-String -LiteralPath $_.FullName -Pattern $target -SimpleMatch -Quiet
        Write-Output ("CACHE {0} containsHookTurn={1}" -f $_.FullName, $hit)
    }
}
Write-Output ("CLAUDE_PLUGIN_ROOT={0}" -f $env:CLAUDE_PLUGIN_ROOT)

